292	  const { mutateAsync: deleteCustomerProductListItem } = useShopperCustomersMutation('deleteCustomerProductListItem');
293	
294	  /**************** Query Actions ****************/
295	  // _refine is an invalid param for useProductSearch, we don't want to pass it to API call
296	  const { _refine, ...restOfParams } = searchParams;
297	
298	  const refine = searchByInventory ? [..._refine, `ilids=${searchByInventory}`] : _refine;
299	
300	  const {
301	    isLoading,
302	    isFetched,
303	    isRefetching,
304	    data: productSearchResult,
305	  } = useProductSearch(
306	    {
307	      parameters: {
308	        ...restOfParams,
309	        perPricebook: true,
310	        allVariationProperties: true,
311	        allImages: true,
312	        expand: [
313	          'promotions',
314	          'variations',
315	          'prices',
316	          'images',
317	          'page_meta_tags',
318	          'custom_properties',
319	          'availability',
320	          'represented_products',
321	        ],
322	        refine,
323	      },
324	    },
325	    {
326	      keepPreviousData: true,
327	    },
328	  );
329	
330	  const { error, data: category } = useCategory(
331	    {
332	      parameters: {
333	        // `enabled` below gates the actual request on a real categoryId; the fallback here only
334	        // satisfies the hook's own parameter type (which does not accept `undefined`) for the
335	        // render where categoryId isn't present yet (e.g. a search-query route).
336	        id: categoryId ?? '',
337	      },
338	    },
339	    {
340	      enabled: !isSearch && !!categoryId,
341	    },
342	  );
343	
344	  // Apply disallow list to refinements.
345	  if (productSearchResult?.refinements) {
346	    productSearchResult.refinements = productSearchResult.refinements.filter(
347	      ({ attributeId }) => !REFINEMENT_DISALLOW_LIST.includes(attributeId),
348	    );
